-- An invoice can be split into scheduled instalments, each an amount due on a date. They are only
-- a schedule for paying the invoice, not money received, so they go with their invoice.
CREATE TABLE invoice_instalment (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id BIGINT         NOT NULL,
    amount     DECIMAL(12, 2) NOT NULL,
    due_date   DATE           NOT NULL,
    CONSTRAINT invoice_instalment_invoice_fk FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE CASCADE,
    CONSTRAINT invoice_instalment_amount_positive CHECK (amount > 0)
);

CREATE INDEX invoice_instalment_invoice_idx ON invoice_instalment (invoice_id);
-- An instalment is marked paid once it has been settled, so the next one due can be told apart.
ALTER TABLE invoice_instalment ADD COLUMN paid BOOLEAN DEFAULT FALSE NOT NULL;
-- A job can have a start date and an end date; either may be unset. The end may not be before the start.
ALTER TABLE project ADD COLUMN start_date DATE;
ALTER TABLE project ADD COLUMN end_date DATE;
ALTER TABLE project ADD CONSTRAINT project_dates_ordered CHECK (end_date IS NULL OR start_date IS NULL OR end_date >= start_date);
-- An instalment paid late accrues interest: a flat amount for each day it is past its due date while
-- still unpaid. The rate is set per invoice; existing invoices charge none.
ALTER TABLE invoice ADD COLUMN instalment_interest_per_day DECIMAL(12, 2) DEFAULT 0 NOT NULL;

ALTER TABLE invoice ADD CONSTRAINT invoice_instalment_interest_per_day_non_negative CHECK (instalment_interest_per_day >= 0);
